import { useCallback, useEffect, useMemo, useState } from 'react';
import { ExternalLink, Globe2, Loader2, RefreshCw, ShieldCheck, Unplug } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { supabase } from '../../../lib/supabase';
import { appToast } from '../../../lib/feedback';

type OAuthGrant = NonNullable<Awaited<ReturnType<typeof supabase.auth.oauth.listGrants>>['data']>[number];

const appHost = (uri: string) => {
  try {
    return new URL(uri).hostname.replace(/^www\./, '');
  } catch {
    return 'Wersee OAuth app';
  }
};

export const OAuthAppsSettings = () => {
  const [grants, setGrants] = useState<OAuthGrant[]>([]);
  const [loading, setLoading] = useState(true);
  const [revoking, setRevoking] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.auth.oauth.listGrants();
      if (error) throw error;
      setGrants(data || []);
    } catch (error) {
      console.error('OAuth applications could not be loaded:', error);
      appToast(error instanceof Error ? error.message : 'OAuth applications could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  const domains = useMemo(() => new Set(grants.map((grant) => appHost(grant.client.uri))).size, [grants]);

  const revoke = async (grant: OAuthGrant) => {
    const confirmed = window.confirm(`Revoke ${grant.client.name}? Its Wersee sessions and refresh tokens will stop working.`);
    if (!confirmed) return;
    setRevoking(grant.client.id);
    try {
      const { error } = await supabase.auth.oauth.revokeGrant({ clientId: grant.client.id });
      if (error) throw error;
      setGrants((current) => current.filter((item) => item.client.id !== grant.client.id));
      appToast(`${grant.client.name} no longer has access to your Wersee account.`);
    } catch (error) {
      appToast(error instanceof Error ? error.message : 'OAuth access could not be revoked.');
    } finally {
      setRevoking(null);
    }
  };

  return (
    <div className="space-y-5">
      <section className="rounded-2xl border border-white/10 bg-[#141414] p-5 md:p-6">
        <div className="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between">
          <div className="max-w-xl">
            <div className="mb-3 flex items-center gap-3">
              <span className="flex h-10 w-10 items-center justify-center rounded-xl border border-white/10 bg-white/5 text-white"><ShieldCheck className="h-5 w-5" /></span>
              <div>
                <p className="text-xs font-semibold uppercase tracking-[0.18em] text-gray-500">Wersee OAuth</p>
                <h3 className="text-lg font-bold text-white">Apps signed in with Wersee</h3>
              </div>
            </div>
            <p className="text-sm leading-6 text-gray-400">Review every app and domain you approved. Revoking an app invalidates its Wersee sessions and refresh tokens without signing you out of Wersee itself.</p>
          </div>
          <button onClick={() => void load()} disabled={loading} className="inline-flex items-center justify-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-2 text-xs font-semibold text-gray-200 transition-colors hover:bg-white/10 disabled:opacity-50">
            <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} /> Refresh
          </button>
        </div>

        <div className="mt-5 grid grid-cols-2 gap-3">
          <div className="rounded-xl border border-white/5 bg-black/25 p-4"><p className="text-2xl font-bold text-white">{grants.length}</p><p className="mt-1 text-xs text-gray-500">Approved apps</p></div>
          <div className="rounded-xl border border-white/5 bg-black/25 p-4"><p className="text-2xl font-bold text-white">{domains}</p><p className="mt-1 text-xs text-gray-500">Connected domains</p></div>
        </div>
      </section>

      <section className="rounded-2xl border border-white/10 bg-[#141414] p-4 md:p-6">
        {loading ? (
          <div className="flex min-h-40 items-center justify-center gap-3 text-sm text-gray-500"><Loader2 className="h-5 w-5 animate-spin" /> Loading approved apps</div>
        ) : grants.length ? (
          <div className="space-y-3">
            {grants.map((grant) => (
              <article key={grant.client.id} className="rounded-2xl border border-white/10 bg-black/20 p-4">
                <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                  <div className="flex min-w-0 items-center gap-3">
                    <span className="flex h-11 w-11 shrink-0 items-center justify-center overflow-hidden rounded-xl border border-white/10 bg-white/5">
                      {grant.client.logo_uri ? <img src={grant.client.logo_uri} alt="" className="h-full w-full object-cover" /> : <Globe2 className="h-5 w-5 text-gray-300" />}
                    </span>
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-2"><h4 className="truncate text-sm font-semibold text-white">{grant.client.name}</h4><span className="rounded-full border border-emerald-400/15 bg-emerald-400/10 px-2 py-0.5 text-[10px] font-semibold text-emerald-300">Active</span></div>
                      <a href={grant.client.uri} target="_blank" rel="noreferrer" className="mt-1 inline-flex max-w-full items-center gap-1 truncate text-xs text-gray-400 hover:text-white">{appHost(grant.client.uri)} <ExternalLink className="h-3 w-3" /></a>
                      <p className="mt-1 text-[11px] text-gray-600">Approved {formatDistanceToNow(new Date(grant.granted_at), { addSuffix: true })}</p>
                    </div>
                  </div>
                  <button onClick={() => void revoke(grant)} disabled={revoking === grant.client.id} className="inline-flex shrink-0 items-center justify-center gap-2 rounded-full border border-red-400/15 bg-red-400/10 px-4 py-2 text-xs font-semibold text-red-300 transition-colors hover:bg-red-400/15 disabled:opacity-50">
                    {revoking === grant.client.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <Unplug className="h-4 w-4" />} Revoke
                  </button>
                </div>
                <div className="mt-4 flex flex-wrap gap-1.5">{grant.scopes.map((scope) => <span key={scope} className="rounded-full border border-white/10 bg-white/5 px-2.5 py-1 text-[11px] text-gray-400">{scope}</span>)}</div>
              </article>
            ))}
          </div>
        ) : (
          <div className="flex min-h-48 flex-col items-center justify-center text-center"><span className="mb-3 flex h-12 w-12 items-center justify-center rounded-2xl border border-white/10 bg-white/5"><ShieldCheck className="h-5 w-5 text-gray-400" /></span><h4 className="text-sm font-semibold text-white">No approved OAuth apps</h4><p className="mt-1 max-w-sm text-xs leading-5 text-gray-500">Apps will appear here after you choose Continue with Wersee and approve access.</p></div>
        )}
      </section>
    </div>
  );
};
